target.css:
:root {
  --bg-card: #f2ead8;
  --bg-header: #2c3e2d;
  --bg-highlight: #e8dfc5;
  --bg-footer: #2c3e2d;
  --border-main: #8b7a55;
  --border-entry: #c9b98a;
  --text-dark: #1e1a10;
  --text-light: #f2ead8;
  --text-muted: #7a6a45;
  --text-callsign: #2c3e2d;
  --accent-strong: #3a6b3a;
  --accent-mid: #b08a20;
  --accent-weak: #8b3a2a;
  --dot-color: #8b7a55;
}

article.log-card {
  width: 480px;
  background-color: var(--bg-card);
  border: 2px solid var(--border-main);
  border-radius: 4px;
  overflow: hidden;
  margin: 0 auto;
}

.log-header {
  background-color: var(--bg-header);
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 10px 16px;
  gap: 12px;
}

.header-left,
.header-right {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 2px;
  min-width: 72px;
}

.header-right {
  align-items: flex-end;
}

.header-left {
  align-items: flex-start;
}

.station-label,
.freq-label {
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.12em;
  color: var(--border-main);
  text-transform: uppercase;
}

.station-id,
.freq-val {
  font-size: 15px;
  font-weight: 700;
  color: var(--text-light);
  letter-spacing: 0.06em;
}

.header-center {
  text-align: center;
  flex: 1;
}

.log-title {
  font-size: 16px;
  font-weight: 800;
  color: var(--text-light);
  letter-spacing: 0.08em;
  text-transform: uppercase;
  margin: 0;
  line-height: 1.2;
}

.log-subtitle {
  font-size: 10px;
  color: var(--border-main);
  letter-spacing: 0.1em;
  margin: 2px 0 0;
}

.log-body {
  padding: 12px 16px;
}

.entry-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 6px;
}

.entry {
  display: grid;
  grid-template-columns: 44px 72px 60px 70px 1fr;
  align-items: center;
  gap: 8px;
  padding: 7px 10px;
  border: 1px solid var(--border-entry);
  border-radius: 3px;
  background-color: var(--bg-card);
}

.entry-highlight {
  background-color: var(--bg-highlight);
  border-color: var(--border-main);
}

.time {
  font-size: 11px;
  font-weight: 700;
  color: var(--text-muted);
  letter-spacing: 0.04em;
}

.callsign {
  font-size: 13px;
  font-weight: 800;
  color: var(--text-callsign);
  letter-spacing: 0.06em;
}

.wpm {
  font-size: 11px;
  color: var(--text-muted);
  font-weight: 600;
}

.signal {
  font-size: 11px;
  font-weight: 700;
  padding: 2px 6px;
  border-radius: 2px;
  text-align: center;
  letter-spacing: 0.04em;
}

.sig-strong {
  color: var(--accent-strong);
  border: 1px solid var(--accent-strong);
}

.sig-mid {
  color: var(--accent-mid);
  border: 1px solid var(--accent-mid);
}

.sig-weak {
  color: var(--accent-weak);
  border: 1px solid var(--accent-weak);
}

.message {
  font-size: 11px;
  color: var(--text-dark);
  font-weight: 600;
  letter-spacing: 0.05em;
  text-transform: uppercase;
}

.log-footer {
  background-color: var(--bg-footer);
  padding: 8px 16px;
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.dots-row {
  display: flex;
  align-items: center;
  gap: 3px;
}

.dot,
.dash {
  display: inline-block;
  background-color: var(--dot-color);
  border-radius: 50%;
  height: 6px;
  width: 6px;
}

.dash {
  width: 14px;
  border-radius: 3px;
}

.footer-meta {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 1px;
}

.op-label {
  font-size: 9px;
  letter-spacing: 0.12em;
  color: var(--border-main);
  font-weight: 700;
  text-transform: uppercase;
}

.op-name {
  font-size: 12px;
  font-weight: 700;
  color: var(--text-light);
  letter-spacing: 0.08em;
}

.footer-date {
  font-size: 11px;
  font-weight: 600;
  color: var(--border-main);
  letter-spacing: 0.06em;
}
